6936,24.47612]],[[118.185444,24.431351],[118.187099,24.435485],[118.189581,24.4372],[118.192888,24.437493],[118.194023,24.440336],[118.197236,24.442372],[118.194934,24.446044],[118.196349,24.450147],[118.199988,24.451757],[118.20379,24.450455],[118.205271,24.447986],[118.205275,24.445416],[118.201759,24.441854],[118.205775,24.436972],[118.204494,24.43224],[118.201423,24.430735],[118.19706,24.431281],[118.195225,24.427811],[118.191568,24.426272],[118.187069,24.427854],[118.185444,24.431351]],[[118.195701,24.39046],[118.191403,24.390899],[118.187084,24.394615],[118.187033,24.399298],[118.190379,24.402398],[118.196381,24.402548],[118.200332,24.398056],[118.200253,24.393335],[118.195701,24.39046]],[[118.139921,24.369753],[118.137083,24.369598],[118.134177,24.371358],[118.133022,24.374033],[118.133554,24.376898],[118.139614,24.383065],[118.147072,24.383243],[118.149886,24.386426],[118.156246,24.388163],[118.153609,24.3941],[118.157324,24.399824],[118.160343,24.401171],[118.162653,24.403817],[118.1652,24.404456],[118.16795,24.403732],[118.170166,24.401375],[118.1733,24.401239],[118.175511,24.399701],[118.176886,24.395737],[118.175655,24.392508],[118.177851,24.388162],[118.17684,24.38398],[118.175225,24.381967],[118.169597,24.379868],[118.167593,24.376721],[118.162069,24.374342],[118.156829,24.37361],[118.150733,24.375753],[118.148211,24.372601],[118.143331,24.372384],[118.139921,24.369753]],[[118.117561,24.362599],[118.118504,24.367049],[118.123819,24.370271],[118.129235,24.369083],[118.131866,24.365591],[118.131617,24.362589],[118.129957,24.360201],[118.124577,24.35775],[118.119979,24.358591],[118.117561,24.362599]]]'::jsonb
    else null end;
  if rings is null then return false; end if;
  for ring in select value from jsonb_array_elements(rings) loop
    hit:=false;
    for i in 0..jsonb_array_length(ring)-1 loop
      a:=ring->i; b:=ring->((i+1)%jsonb_array_length(ring));
      ax:=(a->>0)::numeric; ay:=(a->>1)::numeric; bx:=(b->>0)::numeric; by_:=(b->>1)::numeric;
      cross_value:=(longitude-ax)*(by_-ay)-(latitude-ay)*(bx-ax);
      if abs(cross_value)<0.0000000001 and longitude between least(ax,bx) and greatest(ax,bx)
        and latitude between least(ay,by_) and greatest(ay,by_) then return true; end if;
      if (ay>latitude)<>(by_>latitude) then
        if longitude<(bx-ax)*(latitude-ay)/(by_-ay)+ax then hit:=not hit; end if;
      end if;
    end loop;
    if hit then return true; end if;
  end loop;
  return false;
end;
$$;

create or replace function sync_private.validate_region_geo(body jsonb)
returns void language plpgsql immutable set search_path = '' as $$
begin
  if body ? 'mapProvider' and (body->>'mapProvider' is null or body->>'mapProvider' not in ('google','osm')) then
    raise exception 'Invalid map provider' using errcode='22023';
  end if;
  if body ? 'osmDataset' and (body->>'mapProvider' is distinct from 'osm' or body->>'osmDataset' is null or body->>'osmDataset' not in ('okinawa','taiwan','japan')) then
    raise exception 'Invalid OSM dataset' using errcode='22023';
  end if;
  if body ? 'centerMetadata' then
    perform sync_private.validate_location(body->'centerMetadata',false);
    if not body ? 'center' then raise exception 'Region metadata requires a center'; end if;
    perform sync_private.validate_location((body->'centerMetadata')||jsonb_build_object('coordinate',body->'center'));
  end if;
  if body->>'mapProvider'='osm' then
    if body ? 'googlePlaceId' or not body ?& array['center','centerMetadata']
      or jsonb_typeof(body->'center'->'latitude') is distinct from 'number'
      or jsonb_typeof(body->'center'->'longitude') is distinct from 'number'
      or not public.app_osm_contains(coalesce(body->>'osmDataset','okinawa'),(body->'center'->>'latitude')::numeric,(body->'center'->>'longitude')::numeric) then
      raise exception 'OSM region requires an attributed center inside its dataset' using errcode='22023';
    end if;
  end if;
end;
$$;

create or replace function sync_private.validate_place_geo(body jsonb, provider text)
returns void language plpgsql immutable set search_path = '' as $$
begin
  if body ? 'location' then
    perform sync_private.validate_location(body->'location');
    if body ? 'googlePlaceId' or provider is distinct from 'osm'
      or not (public.app_osm_contains('okinawa',(body->'location'->'coordinate'->>'latitude')::numeric,(body->'location'->'coordinate'->>'longitude')::numeric)
        or public.app_osm_contains('taiwan',(body->'location'->'coordinate'->>'latitude')::numeric,(body->'location'->'coordinate'->>'longitude')::numeric)
        or public.app_osm_contains('japan',(body->'location'->'coordinate'->>'latitude')::numeric,(body->'location'->'coordinate'->>'longitude')::numeric)) then
      raise exception 'Stored places require an OSM region inside a supported dataset' using errcode='22023';
    end if;
  elsif provider='osm' then
    raise exception 'OSM places require stored coordinates' using errcode='22023';
  end if;
end;
$$;


create or replace function public.app_import_place(
  p_name text, p_latitude double precision, p_longitude double precision,
  p_operation_id uuid, p_source_url text default null
)
returns jsonb language plpgsql security invoker set search_path = '' as $$
declare
  uid uuid := auth.uid();
  dataset text;
  region_name text;
  region_center jsonb;
  clean_name text := btrim(p_name);
  normalized_name text;
  region_bytes bytea;
  region_id uuid;
  previous public.places;
  duplicate record;
  record_body jsonb;
  new_location jsonb;
begin
  if uid is null or not public.app_is_member() then
    raise exception '請先使用已開通的 TripMap 帳號登入。' using errcode='42501';
  end if;
  if clean_name is null or clean_name='' or char_length(clean_name)>300
    or p_operation_id is null or p_latitude is null or p_longitude is null
    or not (p_latitude between -90 and 90) or not (p_longitude between -180 and 180) then
    raise exception '請提供有效的名稱、緯度、經度與操作識別碼。' using errcode='22023';
  end if;
  dataset := case when public.app_osm_contains('okinawa',p_latitude::numeric,p_longitude::numeric) then 'okinawa'
    when public.app_osm_contains('taiwan',p_latitude::numeric,p_longitude::numeric) then 'taiwan' when public.app_osm_contains('japan',p_latitude::numeric,p_longitude::numeric) then 'japan' else null end;
  if dataset is null then raise exception '此地點超出支援的沖繩／台灣／日本圖資範圍，尚未新增。' using errcode='22023'; end if;
  region_name := case dataset when 'taiwan' then '台灣' when 'japan' then '日本' else '沖繩' end;
  region_center := case dataset when 'japan' then '{"latitude":35.6812,"longitude":139.7671}'::jsonb when 'taiwan' then '{"latitude":23.7,"longitude":120.95}'::jsonb else '{"latitude":26.44,"longitude":127.97}'::jsonb end;
  if p_source_url is not null and (char_length(p_source_url)>8192
    or p_source_url !~ '^https://[^[:space:]@/]+(/[^[:space:]]*)?$') then
    raise exception '來源網址必須是有效的 HTTPS 網址。' using errcode='22023';
  end if;
  new_location := jsonb_build_object('source','user','kind','user-picked',
    'coordinate',jsonb_build_object('latitude',p_latitude,'longitude',p_longitude));
  normalized_name := lower(regexp_replace(clean_name,'\s+',' ','g'));

  -- Same ordering as existing app_save_place / sync writers. Serializes dedup + create.
  perform pg_advisory_xact_lock(741293,1);
  select * into previous from public.places where id=p_operation_id and owner_uid=uid;
  if found then
    if previous.name is distinct from clean_name or previous.location is distinct from new_location
      or previous.maps_url is distinct from p_source_url then
      raise exception '操作識別碼已使用，請重新送出。' using errcode='22023';
    end if;
    return jsonb_build_object('status','already_imported','placeId',previous.id,'name',previous.name);
  end if;

  -- Match the website's existing duplicate rules: same normalized name OR < 50m.
  select candidate.* into duplicate from (
    select p.id,p.name,
      lower(regexp_replace(btrim(p.name),'\s+',' ','g'))=normalized_name as same_name,
      6371008.8*2*asin(sqrt(least(1.0,greatest(0.0,
        power(sin(radians((p.location->'coordinate'->>'latitude')::double precision-p_latitude)/2),2)
        +cos(radians(p_latitude))*cos(radians((p.location->'coordinate'->>'latitude')::double precision))
        *power(sin(radians((p.location->'coordinate'->>'longitude')::double precision-p_longitude)/2),2)
      )))) as meters
    from public.places p where p.owner_uid=uid and p.location is not null and p.google_place_id is null and exists(select 1 from public.place_regions pr join public.regions r on r.id=pr.region_id where pr.place_id=p.id and r.map_provider='osm' and coalesce(r.osm_dataset,'okinawa')=dataset)
  ) candidate where candidate.same_name or candidate.meters<50
  order by candidate.same_name desc,candidate.id limit 1;
  if found then
    return jsonb_build_object('status','duplicate','placeId',duplicate.id,'name',duplicate.name,
      'reason',case when duplicate.meters<50 then 'nearby' else 'name' end);
  end if;

  -- Same stable account-scoped region ID as src/geo/osm-coverage.ts.
  region_bytes := substring(sha256(convert_to(uid::text||':'||dataset||'-osm-region','UTF8')) for 16);
  region_bytes := set_byte(region_bytes,6,(get_byte(region_bytes,6)&15)|128);
  region_bytes := set_byte(region_bytes,8,(get_byte(region_bytes,8)&63)|128);
  region_id := encode(region_bytes,'hex')::uuid;
  insert into public.regions(id,name,map_provider,center,center_metadata,zoom,osm_dataset)
    values(region_id,region_name,'osm',region_center,
      '{"source":"user","kind":"approximate-center"}',case dataset when 'taiwan' then 7 when 'japan' then 5 else 8 end,case when dataset<>'okinawa' then dataset else null end)
    on conflict(id) do nothing;
  if not exists(select 1 from public.regions where id=region_id and owner_uid=uid and map_provider='osm') then
    raise exception '預設沖繩區域無法使用，請先在 TripMap 確認區域設定。' using errcode='22023';
  end if;
  record_body := jsonb_strip_nulls(jsonb_build_object('name',clean_name,'location',new_location,
    'mapsUrl',p_source_url,'regionIds',jsonb_build_array(region_id),'labelIds','[]'::jsonb));
  perform public.app_save_place(p_operation_id,record_body,true);
  return jsonb_build_object('status','created','placeId',p_operation_id,'name',clean_name,'regionId',region_id);
end;
$$;
commit;
